        context.screen_height = height;
        context.players[0].enabled = true;
        context.players[1].enabled = second;
        let mut p = Pair::new(&context);
        p.compare("SL={Global={GameMode='ITG',ActiveModifiers={MusicRate=1.25}},Metrics={ITG={}}}");
        for group in [
            "Common",
            "ScreenGameplay",
            "Player",
            "Combo",
            "GraphDisplay",
