#[test]
fn theme_font_paths_and_metrics_feed_owned_actor_resources() {
    let source = r#"return LoadFont(THEME:GetPathF('Common','Normal'))..{
        Text=THEME:GetString('Difficulty','Difficulty_Hard'),
        InitCommand=function(self)label=self;self:zoom(THEME:GetMetricF('LifeMeterBar','InitialValue'))end}
    "#;
    for live in [false, true] {
        let mut context = context();
        context.live = live;
        let legacy = test_support::legacy_actor_scene_with_setup(source, &context, |lua| {
            lua.globals()
                .set("THEME", song::create_theme_table(lua, &context)?)
        })
        .unwrap();
        let mut rust = RustSongRuntime::new(&context).unwrap();
        let declaration = execute(&mut rust, source)[0];
        let scene = rust.instantiate_actor(declaration).unwrap();
        let label = rust.vm_mut().get_global(b"label").unwrap();
        assert_eq!(
            format!("{:?}", rust.actor_bitmap_text(label).unwrap()),
            format!(
                "{:?}",
                test_support::legacy_bitmap_text(&legacy, "label").unwrap()
            )
        );
        let actual = rust.actor_scene_snapshot(scene).unwrap();
        let expected = test_support::legacy_actor_render_states(&legacy).unwrap();
        assert_eq!(actual.len(), expected.len());
        for (a, b) in actual.iter().zip(expected) {
            assert_eq!(format!("{:?}", a.render), format!("{b:?}"));
        }
        rust.release_actor_scene(scene).unwrap();
    }
}

